for(const kind of ['clip','audio-clip'])add('take lane '+kind+' create',s=>{const lane=withLane(s);return [{method:'replaceState',value:s},invoke('take-lane.'+kind+'.create',{takeLaneRef:lane.ref,expectedTakeLaneIdentity:lane.objectIdentity,expectedCollectionRevision:rev([]),position:1.5,length:8,name:'Take Clip',filePath:'/tmp/take.wav'})]});
add('take lane audio path validation',s=>{const lane=withLane(s);return [{method:'replaceState',value:s},invoke('take-lane.audio-clip.create',{takeLaneRef:lane.ref,expectedTakeLaneIdentity:lane.objectIdentity,expectedCollectionRevision:rev([]),position:1,filePath:'relative.wav'})]});
writeFileSync(new URL('./simulator-oracle.json',import.meta.url),'[\n'+scenarios.map(JSON.stringify).join(',\n')+'\n]\n');
const errors=[];for(const scenario of scenarios){if(scenario.steps[0]?.method!=='invoke')continue;const base=scenario.steps.find(s=>s.method==='invoke'&&s.result!==undefined)?.invocation;if(!base)continue;for(const key of Object.keys(base.args))for(const kind of ['missing','null']){let invocation=structuredClone(base);if(kind==='missing')delete invocation.args[key];else invocation.args[key]=null;try{new DeterministicLiveSimulator().invoke(invocation);}catch(e){errors.push({name:scenario.name+' '+key+' '+kind,invocation,error:e.message});}}}
writeFileSync(new URL('./simulator-errors.json',import.meta.url),'[\n'+errors.map(JSON.stringify).join(',\n')+'\n]\n');
